// KMP: build failure function (LPS array), then search
function kmpSearch(text, pattern) {
  const n = text.length, m = pattern.length;
  if (m === 0) return [];

  // Step 1: build LPS (Longest Proper Prefix = Suffix) array
  const lps = new Array(m).fill(0);
  let len = 0, i = 1;
  while (i < m) {
    if (pattern[i] === pattern[len]) {
      lps[i++] = ++len;
    } else if (len > 0) {
      len = lps[len - 1]; // fall back - do NOT increment i
    } else {
      lps[i++] = 0;
    }
  }

  // Step 2: search text using the LPS array
  const matches = [];
  let j = 0; // pointer into pattern
  i = 0;     // pointer into text
  while (i < n) {
    if (text[i] === pattern[j]) {
      i++; j++;
    }
    if (j === m) {
      matches.push(i - m); // match starts here
      j = lps[j - 1];      // continue for overlapping matches
    } else if (i < n && text[i] !== pattern[j]) {
      if (j > 0) j = lps[j - 1]; // shift pattern
      else i++;                   // advance text
    }
  }
  return matches;
}
